use super::*;
use serde_json::json;
fn payloads() -> Vec<Value> {
    // These transport inputs belong to AGR-ENC-03's independently compared
    // selected snapshot, rather than values generated by this codec.
    let fixture:Value=serde_json::from_slice(include_bytes!("../../../../../../contracts/candidates/full-suite-v1/core/agreement-03-primary-author.json")).unwrap();
    fixture["operations"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|v| v["normalized_request"]["kind"] == "evidence.retain")
        .map(|v| v["normalized_request"]["payload"].clone())
        .collect()
}
#[test]
fn all_selected_purposes_preserve_exact_compared_payload_bytes() {
    let values = payloads();
    let mut purposes = std::collections::BTreeSet::new();
    for v in values {
        let raw = CanonicalBytes::from_value(&v).unwrap();
        let input = EvidenceInput::parse(raw.as_slice()).unwrap();
        assert_eq!(input.canonical_bytes(), raw.as_slice());
        assert_eq!(input.canonical_value().unwrap(), v);
        purposes.insert(input.purpose().to_owned());
        assert!(!input.content().is_empty());
    }
    assert_eq!(purposes.len(), 6);
}
#[test]
fn strict_raw_unknown_null_and_metadata_union_refuse() {
    let v = payloads().remove(0);
    let raw = serde_json::to_string(&v).unwrap();
    assert!(
        EvidenceInput::parse(raw.replacen('{', "{\"purpose\":\"assent\",", 1).as_bytes()).is_err()
    );
    for (key, value) in [
        ("retained_by", json!("caller")),
        ("metadata", json!({"acceptor":"customer-A","admin":true})),
        (
            "subject",
            json!({"customer":"customer-A","agreement_id":null}),
        ),
        ("purpose", json!("unknown")),
    ] {
        let mut wrong = v.clone();
        wrong[key] = value;
        assert!(EvidenceInput::parse(&serde_json::to_vec(&wrong).unwrap()).is_err());
    }
}
#[test]
fn canonical_base64_hash_and_decoded_limit_are_required() {
    let v = payloads().remove(0);
    for text in ["YQ", "YR==", "YQ=", "YQ==\n", "", "YQ--"] {
        let mut wrong = v.clone();
        wrong["content_base64"] = json!(text);
        assert!(EvidenceInput::parse(&serde_json::to_vec(&wrong).unwrap()).is_err());
    }
    for (tail, count, accepted) in [("YQ==", 4096, true), ("YWE=", 4097, false)] {
        let mut changed = v.clone();
        changed["content_base64"] = json!(format!("{}{tail}", "YWFh".repeat(1365)));
        changed["content_sha256"] = json!(canonical::hex(&Sha256::digest(vec![b'a'; count])));
        assert_eq!(
            EvidenceInput::parse(&serde_json::to_vec(&changed).unwrap()).is_ok(),
            accepted
        );
    }
    let mut wrong = v;
    wrong["content_sha256"] = json!("0".repeat(64));
    assert!(EvidenceInput::parse(&serde_json::to_vec(&wrong).unwrap()).is_err());
}
#[test]
fn operator_and_stop_references_cannot_change_family_or_metadata() {
    for mut v in payloads() {
        match v["purpose"].as_str().unwrap() {
            "operator_attestation" => {
                v["metadata"]["assent_evidence_ref"]["kind"] = json!("workflow-authority");
                assert!(EvidenceInput::parse(&serde_json::to_vec(&v).unwrap()).is_err());
            }
            "admission_stop" => {
                v["metadata"]["target_transition_ref"]["kind"] = json!("workflow-head-transition");
                assert!(EvidenceInput::parse(&serde_json::to_vec(&v).unwrap()).is_err());
            }
            _ => (),
        }
    }
}
